head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[video > P > controls]<br/>Video 컴포넌트에 브라우저가 제공하는 기본 재생 컨트롤을 표시할지 설정합니다.",
    "validation" : [
        "controls 설정 시, 브라우저가 제공하는 기본 재생 컨트롤을 화면에 표시합니다.",
        "빈 문자열('') 을 설정해도 기본 재생 컨트롤을 화면에 표시합니다.",
        "컴포넌트 정의 시 필수 속성으로 함께 정의되므로 기본 재생 컨트롤은 항상 Video 컴포넌트에 표시됩니다."
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// video 요소의 렌더 영역 크기 문자열 반환 (컨트롤 표시 여부 판정의 보조 근거)
scwin.getRenderSize = function (el) {
    let oRect = el.getBoundingClientRect();
    return Math.round(oRect.width) + " x " + Math.round(oRect.height);
};



// controls 설정값별 기본 재생 컨트롤 표시 여부 확인
scwin.btn_getControlsDisplay_onclick = function (e) {
    let el1 = document.querySelector("#target1");
    let el2 = document.querySelector("#target2");
    let el3 = document.querySelector("#target3");
    let nShownCount = [el1, el2, el3].filter(function (el) { return el.controls === true; }).length;

    wf_body_bottom.getObj("scwin").setReturnValue("controls 를 controls 로 설정 - controls 속성값 : " + JSON.stringify(el1.getAttribute("controls")) + " , controls 프로퍼티 : " + el1.controls + " , 렌더 영역(너비 x 높이) : " + scwin.getRenderSize(el1));
    wf_body_bottom.getObj("scwin").setReturnValue("controls 를 빈 문자열로 설정 - controls 속성값 : " + JSON.stringify(el2.getAttribute("controls")) + " , controls 프로퍼티 : " + el2.controls + " , 렌더 영역(너비 x 높이) : " + scwin.getRenderSize(el2));
    wf_body_bottom.getObj("scwin").setReturnValue("필수 속성으로 항상 표시 - 속성을 정의하지 않은 target3 의 controls 속성값 : " + JSON.stringify(el3.getAttribute("controls")) + " , controls 프로퍼티 : " + el3.controls + " , 렌더 영역(너비 x 높이) : " + scwin.getRenderSize(el3) + " , 컨트롤이 표시된 video 개수 : " + nShownCount + " / 3");
};
